#!/usr/bin/env Rscript
# Sensitivity only: remove an own-target UPR member from the numerator; denominator stays fixed.
suppressPackageStartupMessages(library(data.table));a<-commandArgs(TRUE);out<-if(length(a))a[1]else'paper19opp-revision2/reconstruction/candidate_validation';set.seed(202611064L);B<-2000L;P<-10000L
m<-fread(file.path(out,'UPR_exact_numerator_denominator_moments.tsv'));s<-m[study=='Replogle2022',.(gene,source_effect=effect_z)];original<-fread(file.path(out,'exploratory_axis_conservation.tsv'));rows<-list();pairs<-list()
for(st in setdiff(unique(m$study),'Replogle2022'))for(ctx in unique(m[study==st,context])){
 x<-merge(s,m[study==st&context==ctx,.(gene,external_effect=effect_z)],by='gene');base<-fread(file.path(out,if(st=='Adamson2016')'harmonized_adamson_candidates.tsv'else'harmonized_frangieh_candidates.tsv'))$gene;x<-x[gene%in%base];if(st=='Frangieh2021'){cnt<-fread(file.path(out,'frangieh_cell_scores_harmonized.tsv.gz'),select=c('gene','context'));avail<-cnt[context==ctx,.N,by=gene][N>=30,gene];x<-x[gene%in%avail]};n<-nrow(x);rho<-cor(x$source_effect,x$external_effect,method='spearman');bb<-vapply(seq_len(B),function(b){ii<-sample.int(n,n,replace=TRUE);cor(x$source_effect[ii],x$external_effect[ii],method='spearman')},numeric(1));pn<-vapply(seq_len(P),function(b)cor(x$source_effect,x$external_effect[sample.int(n)],method='spearman'),numeric(1));qq<-quantile(bb,c(.025,.975));rows[[length(rows)+1L]]<-data.table(study=st,context=ctx,axis='hallmark_UNFOLDED_PROTEIN_RESPONSE',genes=n,spearman=rho,conditional_gene_bootstrap_low=qq[1],conditional_gene_bootstrap_high=qq[2],two_sided_gene_permutation_p=(1+sum(abs(pn)>=abs(rho)-1e-12))/(P+1),minimum_leave_one_gene_out=min(vapply(seq_len(n),function(i)cor(x$source_effect[-i],x$external_effect[-i],method='spearman'),numeric(1))),maximum_leave_one_gene_out=max(vapply(seq_len(n),function(i)cor(x$source_effect[-i],x$external_effect[-i],method='spearman'),numeric(1))))
}
r<-rbindlist(rows);family<-copy(original);family<-family[axis!='hallmark_UNFOLDED_PROTEIN_RESPONSE',.(study,context,axis,genes,spearman,conditional_gene_bootstrap_low,conditional_gene_bootstrap_high,two_sided_gene_permutation_p)];family<-rbind(family,r[,.(study,context,axis,genes,spearman,conditional_gene_bootstrap_low,conditional_gene_bootstrap_high,two_sided_gene_permutation_p)]);stopifnot(nrow(family)==48);family[,BH_q_sensitivity_all48:=p.adjust(two_sided_gene_permutation_p,'BH')];r<-merge(r,family[,.(study,context,axis,BH_q_sensitivity_all48)],by=c('study','context','axis'));r[,scope:='Exact own-target numerator AND normalization-denominator exclusion where measured'];fwrite(r,file.path(out,'UPR_exact_composition_correlation_sensitivity.tsv'),sep='\t');fwrite(family,file.path(out,'UPR_exact_composition_full48_sensitivity.tsv'),sep='\t');print(r)
